import { Hono } from 'hono';
import { getCookie, setCookie, deleteCookie } from 'hono/cookie';

type Env={DB:D1Database;MEDIA?:R2Bucket;ASSETS:Fetcher;SESSION_SECRET:string;TOKEN_ENCRYPTION_KEY?:string;RESEND_API_KEY?:string;RESEND_FROM_EMAIL?:string;ADMIN_OWNER_EMAIL?:string;SITE_NAME:string;PHONE:string;MAPS_URL:string;ADMIN_HOST?:string;INSTAGRAM_ACCESS_TOKEN?:string;INSTAGRAM_USER_ID?:string;INSTAGRAM_GRAPH_VERSION?:string;INSTAGRAM_APP_ID?:string;INSTAGRAM_APP_SECRET?:string;INSTAGRAM_REDIRECT_URI?:string;YOUTUBE_API_KEY?:string;YOUTUBE_CHANNEL_HANDLE?:string;GOOGLE_PLACES_API_KEY?:string;GOOGLE_PLACE_ID?:string};
const app=new Hono<{Bindings:Env}>();
function hostMatchesConfiguredAdmin(c:any){const configured=String(c.env.ADMIN_HOST||'').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/\/$/,'');if(!configured)return false;const requestHost=new URL(c.req.url).host.toLowerCase();return requestHost===configured||requestHost.split(':')[0]===configured.split(':')[0]}
app.use('*',async(c,next)=>{const sensitive=c.req.path.startsWith('/admin')||c.req.path.startsWith('/api/admin')||['/api/login','/api/logout','/api/me','/api/setup','/api/setup/status'].includes(c.req.path);if(sensitive&&!hostMatchesConfiguredAdmin(c))return c.notFound();if(c.req.method!=='GET'&&c.req.method!=='HEAD'&&c.req.method!=='OPTIONS'&&(c.req.path.startsWith('/api/admin')||['/api/login','/api/logout','/api/setup/request-code','/api/setup/verify-code','/api/setup/create'].includes(c.req.path))&&!sameOriginRequest(c))return c.json({error:'Invalid request origin'},403);await next()});
app.use('*',async(c,next)=>{await next();c.header('X-Content-Type-Options','nosniff');c.header('Referrer-Policy','strict-origin-when-cross-origin');c.header('X-Frame-Options','DENY');c.header('Permissions-Policy','camera=(),microphone=(),geolocation=()');c.header('Content-Security-Policy',"default-src 'self'; img-src 'self' data: https:; style-src 'self' 'unsafe-inline'; script-src 'self' https://www.youtube.com; frame-src https://player.vimeo.com https://www.youtube.com https://www.youtube-nocookie.com https://www.instagram.com; connect-src 'self' https://www.youtube.com; object-src 'none'; base-uri 'self'; frame-ancestors 'none'");});
const enc=new TextEncoder();
async function hmac(env:Env,value:string){if(!env.SESSION_SECRET||env.SESSION_SECRET.length<32)throw new Error('SESSION_SECRET is not configured correctly');const k=await crypto.subtle.importKey('raw',enc.encode(env.SESSION_SECRET),{name:'HMAC',hash:'SHA-256'},false,['sign','verify']);return crypto.subtle.sign('HMAC',k,enc.encode(value)).then(x=>btoa(String.fromCharCode(...new Uint8Array(x))));}
function b64u(bytes:ArrayBuffer|Uint8Array){const a=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes);return btoa(String.fromCharCode(...a)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function unb64u(s:string){const t=s.replace(/-/g,'+').replace(/_/g,'/');return Uint8Array.from(atob(t+'='.repeat((4-t.length%4)%4)),x=>x.charCodeAt(0))}
async function tokenKey(env:Env,legacy=false){const secret=legacy||!env.TOKEN_ENCRYPTION_KEY?env.SESSION_SECRET:env.TOKEN_ENCRYPTION_KEY!;const digest=await crypto.subtle.digest('SHA-256',enc.encode(secret));return crypto.subtle.importKey('raw',digest,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function encryptToken(env:Env,value:string){const iv=crypto.getRandomValues(new Uint8Array(12));const ct=await crypto.subtle.encrypt({name:'AES-GCM',iv},await tokenKey(env),enc.encode(value));return `${b64u(iv)}.${b64u(ct)}`}
async function decryptToken(env:Env,value:string){const [ivS,ctS]=value.split('.');if(!ivS||!ctS)throw new Error('Invalid encrypted token');try{const pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64u(ivS)},await tokenKey(env),unb64u(ctS));return new TextDecoder().decode(pt)}catch(e){if(env.TOKEN_ENCRYPTION_KEY){const pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64u(ivS)},await tokenKey(env,true),unb64u(ctS));return new TextDecoder().decode(pt)}throw e}}
async function instagramRedirect(c:any){return c.env.INSTAGRAM_REDIRECT_URI||new URL('/api/instagram/callback',c.req.url).toString()}
async function getInstagramConnection(c:any){const row:any=await c.env.DB.prepare('SELECT * FROM instagram_integrations WHERE provider=? LIMIT 1').bind('instagram').first();if(row?.access_token_enc){try{return {...row,access_token:await decryptToken(c.env,row.access_token_enc)}}catch{}}if(c.env.INSTAGRAM_ACCESS_TOKEN&&c.env.INSTAGRAM_USER_ID)return {provider:'instagram',user_id:c.env.INSTAGRAM_USER_ID,access_token:c.env.INSTAGRAM_ACCESS_TOKEN,username:null,expires_at:null};return null}
async function refreshInstagramToken(c:any,conn:any){if(!conn?.access_token)return conn;const version=c.env.INSTAGRAM_GRAPH_VERSION||'v24.0';if(conn.expires_at&&Number(conn.expires_at)-Date.now()>7*86400000)return conn;if(!c.env.INSTAGRAM_APP_SECRET)return conn;const u=new URL(`https://graph.instagram.com/${version}/refresh_access_token`);u.searchParams.set('grant_type','ig_refresh_token');u.searchParams.set('access_token',conn.access_token);const r=await fetch(u);const d:any=await r.json();if(!r.ok||!d.access_token)return conn;const expiresAt=Date.now()+Number(d.expires_in||5184000)*1000;await c.env.DB.prepare('UPDATE instagram_integrations SET access_token_enc=?,expires_at=?,updated_at=CURRENT_TIMESTAMP WHERE provider=?').bind(await encryptToken(c.env,d.access_token),expiresAt,'instagram').run();return {...conn,access_token:d.access_token,expires_at:expiresAt}}
const PASSWORD_ITERATIONS=100000;
async function hashPassword(p:string){const salt=crypto.getRandomValues(new Uint8Array(16));const key=await crypto.subtle.importKey('raw',enc.encode(p),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:PASSWORD_ITERATIONS,hash:'SHA-256'},key,256);return `pbkdf2$${PASSWORD_ITERATIONS}$${btoa(String.fromCharCode(...salt))}$${btoa(String.fromCharCode(...new Uint8Array(bits)))}`;}
async function verifyPassword(p:string,stored:string){try{const [,it,s,b]=stored.split('$');const salt=Uint8Array.from(atob(s),x=>x.charCodeAt(0));const key=await crypto.subtle.importKey('raw',enc.encode(p),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:Number(it),hash:'SHA-256'},key,256);return btoa(String.fromCharCode(...new Uint8Array(bits)))===b}catch{return false}}
async function session(c:any,env:Env){const id=getCookie(c,'ip_session');if(!id)return null;const sig=getCookie(c,'ip_sig');if(!sig||await hmac(env,id)!==sig)return null;return c.env.DB.prepare('SELECT a.id,a.name,a.email,a.role FROM sessions s JOIN admins a ON a.id=s.admin_id WHERE s.id=? AND s.expires_at>? AND a.active=1').bind(id,Date.now()).first()}
function uid(){return crypto.randomUUID()}
function clientIp(c:any){return (c.req.header('CF-Connecting-IP')||c.req.header('X-Forwarded-For')||'unknown').split(',')[0].trim().slice(0,80)}
function sameOriginRequest(c:any){const origin=c.req.header('Origin');if(origin){try{return new URL(origin).origin===new URL(c.req.url).origin}catch{return false}}const referer=c.req.header('Referer');if(referer){try{return new URL(referer).origin===new URL(c.req.url).origin}catch{return false}}return true}
function textField(v:any,max:number){return String(v??'').trim().slice(0,max)}
function validEmail(v:any){const e=String(v??'').trim().toLowerCase();return e.length<=320&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)}
function boundedInt(v:any,min:number,max:number,def=0){const n=Number(v);return Number.isInteger(n)&&n>=min&&n<=max?n:def}
function finiteNumber(v:any,min:number,max:number,def=0){const n=Number(v);return Number.isFinite(n)&&n>=min&&n<=max?n:def}
function validMediaUrl(v:string){if(!v)return true;if(v.startsWith('/media/'))return true;try{const u=new URL(v);return u.protocol==='https:'||u.protocol==='http:'}catch{return false}}
async function clearRateLimit(c:any,...keys:string[]){if(keys.length)await c.env.DB.batch(keys.map(k=>c.env.DB.prepare('DELETE FROM auth_rate_limits WHERE key=?').bind(k)))}
async function rateLimit(c:any,key:string,max:number,windowMs:number,blockMs=windowMs){const now=Date.now();const row:any=await c.env.DB.prepare('SELECT window_start,count,blocked_until FROM auth_rate_limits WHERE key=?').bind(key).first();if(row?.blocked_until&&Number(row.blocked_until)>now)return false;const start=Number(row?.window_start||0);if(!row||now-start>=windowMs){await c.env.DB.prepare('INSERT INTO auth_rate_limits(key,window_start,count,blocked_until) VALUES(?,?,1,0) ON CONFLICT(key) DO UPDATE SET window_start=excluded.window_start,count=1,blocked_until=0').bind(key,now).run();return true}const count=Number(row.count||0)+1;const blocked=count>max;await c.env.DB.prepare('UPDATE auth_rate_limits SET count=?,blocked_until=? WHERE key=?').bind(count,blocked?now+blockMs:0,key).run();return !blocked}
function setupOwnerEmails(env:Env){return String(env.ADMIN_OWNER_EMAIL||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean)}
async function storageUsed(c:any){const used:any=await c.env.DB.prepare('SELECT COALESCE(SUM(bytes),0) bytes FROM photos WHERE r2_key IS NOT NULL').first();return Number(used?.bytes||0)}
async function reserveStorage(c:any,id:string,bytes:number){if(!c.env.MEDIA)return true;const used=await storageUsed(c);const r=await c.env.DB.prepare('UPDATE storage_quota SET reserved_bytes=reserved_bytes+? WHERE id=1 AND reserved_bytes+?+?<=2147483648').bind(bytes,bytes,used).run();if(Number(r.meta?.changes||0)!==1)return false;try{await c.env.DB.prepare('INSERT INTO storage_reservations(id,bytes,expires_at) VALUES(?,?,?)').bind(id,bytes,Date.now()+20*60*1000).run();return true}catch(e){await c.env.DB.prepare('UPDATE storage_quota SET reserved_bytes=MAX(0,reserved_bytes-?) WHERE id=1').bind(bytes).run();throw e}}
async function releaseStorage(c:any,id:string){const row:any=await c.env.DB.prepare('SELECT bytes FROM storage_reservations WHERE id=?').bind(id).first();if(!row)return;await c.env.DB.batch([c.env.DB.prepare('DELETE FROM storage_reservations WHERE id=?').bind(id),c.env.DB.prepare('UPDATE storage_quota SET reserved_bytes=MAX(0,reserved_bytes-?) WHERE id=1').bind(Number(row.bytes||0))])}
async function finalizeStorage(c:any,id:string){return releaseStorage(c,id)}

function instagramCategory(caption:string){const tags=(caption.match(/#[\p{L}0-9_-]+/gu)||[]).map(t=>t.slice(1).toLowerCase().replace(/[_\s-]/g,''));const map:[string,string[]][]=[['Beach',['beach']],['Birthday',['birthday']],['Family',['family']],['Maternity',['maternity']],['Portfolio',['portfolio']],['Pre-Wedding',['prewedding']],['Wedding',['wedding']]];for(const tag of tags){const hit=map.find(([,aliases])=>aliases.includes(tag));if(hit)return hit[0]}return 'Other'}
async function requireAuth(c:any,next:any){const a=await session(c,c.env);if(!a)return c.json({error:'Unauthorized'},401);c.set('admin',a);await next()}
async function instagramAuthorize(c:any){if(!c.env.INSTAGRAM_APP_ID)return c.text('Instagram connection is not configured on this Worker.',500);const state=uid();const sig=await hmac(c.env,state);setCookie(c,'ig_oauth_state',`${state}.${sig}`,{httpOnly:true,secure:true,sameSite:'Lax',path:'/api/instagram',maxAge:600});const u=new URL('https://www.instagram.com/oauth/authorize');u.searchParams.set('force_reauth','true');u.searchParams.set('client_id',c.env.INSTAGRAM_APP_ID);u.searchParams.set('redirect_uri',await instagramRedirect(c));u.searchParams.set('response_type','code');u.searchParams.set('scope','instagram_business_basic');u.searchParams.set('state',state);return c.redirect(u.toString(),302)}
app.get('/api/instagram/connect',async c=>instagramAuthorize(c));
app.post('/api/admin/instagram/connect-link',requireAuth,async c=>{if(!c.env.INSTAGRAM_APP_ID||!c.env.INSTAGRAM_APP_SECRET)return c.json({error:'Instagram app credentials are not configured on this Worker.'},500);const raw=b64u(crypto.getRandomValues(new Uint8Array(32)));const tokenHash=await sha256(raw);const expiresAt=Date.now()+30*60*1000;await c.env.DB.prepare('DELETE FROM instagram_connection_links WHERE expires_at<=? OR used_at IS NOT NULL').bind(Date.now()).run();await c.env.DB.prepare('INSERT INTO instagram_connection_links(token_hash,expires_at) VALUES(?,?)').bind(tokenHash,expiresAt).run();const url=new URL(`/api/instagram/connect-link/${raw}`,c.req.url).toString();return c.json({ok:true,url,expiresAt});});
app.get('/api/instagram/connect-link/:token',async c=>{const token=c.req.param('token');if(!/^[A-Za-z0-9_-]{40,60}$/.test(token))return c.text('Invalid connection link.',400);const row:any=await c.env.DB.prepare('SELECT expires_at,used_at FROM instagram_connection_links WHERE token_hash=?').bind(await sha256(token)).first();if(!row||row.used_at||Number(row.expires_at)<=Date.now())return c.html('<h2>Connection link expired</h2><p>Please ask the photographer to create a new Instagram connection link.</p>',410);return c.html(`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Connect Instagram · Impression Photography</title><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#080c0f;color:#f5f7f8;font-family:Arial,sans-serif}.card{width:min(460px,88vw);padding:32px;border:1px solid #273137;border-radius:20px;background:#11181d;text-align:center}.eyebrow{color:#e5c38d;font-size:11px;letter-spacing:.2em;font-weight:800}.card h1{font:600 36px Georgia,serif;margin:12px 0}.card p{color:#9da8ae;line-height:1.6}.btn{display:inline-block;margin-top:12px;padding:13px 20px;border-radius:999px;background:#f5f7f8;color:#080c0f;text-decoration:none;font-weight:700;border:0;cursor:pointer}</style></head><body><main class="card"><div class="eyebrow">IMPRESSION PHOTOGRAPHY</div><h1>Connect Instagram</h1><p>This secure one-time link lets you authorize the photography website to access your Instagram media. You will log in to Instagram yourself. Your password is never shared with the photographer.</p><form method="post" action="/api/instagram/connect-link/${token}/start"><button class="btn" type="submit">Continue to Instagram</button></form><p>This link expires in 30 minutes and can be used once.</p></main></body></html>`)});
app.post('/api/instagram/connect-link/:token/start',async c=>{const token=c.req.param('token');if(!/^[A-Za-z0-9_-]{40,60}$/.test(token))return c.text('Invalid connection link.',400);const now=Date.now();const result:any=await c.env.DB.prepare('UPDATE instagram_connection_links SET used_at=? WHERE token_hash=? AND used_at IS NULL AND expires_at>?').bind(now,await sha256(token),now).run();if(Number(result.meta?.changes||0)!==1)return c.html('<h2>Connection link expired or already used</h2><p>Please ask the photographer to create a new Instagram connection link.</p>',410);return instagramAuthorize(c)});
app.get('/api/instagram/callback',async c=>{const err=c.req.query('error');if(err)return c.html(`<h2>Instagram connection cancelled</h2><p>${String(c.req.query('error_description')||err).replace(/[<>]/g,'')}</p><p>You can close this window.</p>`);const code=c.req.query('code');const state=c.req.query('state');const saved=getCookie(c,'ig_oauth_state');deleteCookie(c,'ig_oauth_state',{path:'/api/instagram'});if(!code)return c.text('Instagram did not return an authorization code.',400);if(!state||!saved){return c.text('Instagram connection state is missing. Please start again from the connection link.',400)}const [savedState,savedSig]=saved.split('.');if(state!==savedState||savedSig!==await hmac(c.env,state))return c.text('Instagram connection state could not be verified. Please start again.',400);if(!c.env.INSTAGRAM_APP_ID||!c.env.INSTAGRAM_APP_SECRET)return c.text('Instagram app credentials are not configured on this Worker.',500);const redirectUri=await instagramRedirect(c);try{const shortResp=await fetch('https://api.instagram.com/oauth/access_token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:c.env.INSTAGRAM_APP_ID,client_secret:c.env.INSTAGRAM_APP_SECRET,grant_type:'authorization_code',redirect_uri:redirectUri,code})});const short:any=await shortResp.json();if(!shortResp.ok||!short.access_token)throw new Error(short?.error_message||short?.error?.message||'Instagram token exchange failed');const longUrl=new URL('https://graph.instagram.com/access_token');longUrl.searchParams.set('grant_type','ig_exchange_token');longUrl.searchParams.set('client_secret',c.env.INSTAGRAM_APP_SECRET);longUrl.searchParams.set('access_token',short.access_token);const longResp=await fetch(longUrl);const long:any=await longResp.json();if(!longResp.ok||!long.access_token)throw new Error(long?.error?.message||long?.error_message||'Instagram long-lived token exchange failed');const version=c.env.INSTAGRAM_GRAPH_VERSION||'v24.0';const meUrl=new URL(`https://graph.instagram.com/${version}/me`);meUrl.searchParams.set('fields','id,username');meUrl.searchParams.set('access_token',long.access_token);const meResp=await fetch(meUrl);const me:any=await meResp.json();if(!meResp.ok||!me.id)throw new Error(me?.error?.message||'Could not read the connected Instagram account');const expiresAt=Date.now()+Number(long.expires_in||5184000)*1000;await c.env.DB.prepare(`INSERT INTO instagram_integrations(provider,user_id,username,access_token_enc,expires_at,created_at,updated_at) VALUES(?,?,?,?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(provider) DO UPDATE SET user_id=excluded.user_id,username=excluded.username,access_token_enc=excluded.access_token_enc,expires_at=excluded.expires_at,updated_at=CURRENT_TIMESTAMP`).bind('instagram',String(me.id),String(me.username||''),await encryptToken(c.env,String(long.access_token)),expiresAt).run();return c.html(`<h2>Instagram connected successfully</h2><p>Connected account: <strong>${String(me.username||me.id).replace(/[<>]/g,'')}</strong></p><p>You can close this window and return to the website.</p>`)}catch(e:any){return c.html(`<h2>Instagram connection failed</h2><p>${String(e?.message||e).replace(/[<>]/g,'')}</p><p>Please start the connection again.</p>`,500)}});
app.get('/api/instagram/status',requireAuth,async c=>{const conn=await getInstagramConnection(c);return c.json({connected:Boolean(conn),username:conn?.username||null})});
app.get('/api/public',async c=>{const [s,v,p]=await Promise.all([c.env.DB.prepare('SELECT id,title,description,image_url,active,sort_order FROM services WHERE active=1 ORDER BY sort_order,id').all(),c.env.DB.prepare('SELECT * FROM videos WHERE active=1 ORDER BY sort_order,id').all(),c.env.DB.prepare("SELECT id,source,source_id,image_url,caption,occasion,category FROM photos WHERE published=1 ORDER BY created_at DESC LIMIT 200").all()]);return c.json({services:s.results,videos:v.results,photos:p.results,phone:c.env.PHONE,maps:c.env.MAPS_URL});});
app.get('/api/reviews',async c=>{const key=c.env.GOOGLE_PLACES_API_KEY;const placeId=c.env.GOOGLE_PLACE_ID||'ChIJmeK4XLzBvzsR5X9N1oBatPc';if(!key)return c.json({reviews:[],rating:null,count:0,mapsUrl:c.env.MAPS_URL||'https://maps.google.com/?cid=17848990732573835237&entry=gps'});try{const r=await fetch(`https://places.googleapis.com/v1/places/${encodeURIComponent(placeId)}`,{headers:{'X-Goog-Api-Key':key,'X-Goog-FieldMask':'displayName,rating,userRatingCount,reviews,googleMapsUri'}});const d:any=await r.json();if(!r.ok)return c.json({reviews:[],rating:null,count:0,mapsUrl:c.env.MAPS_URL||'https://maps.google.com/?cid=17848990732573835237&entry=gps',error:d?.error?.message||'Google Places request failed'},502);const reviews=(d.reviews||[]).map((x:any)=>({id:x.name||x.authorAttribution?.uri||Math.random().toString(36),authorName:x.authorAttribution?.displayName||'Google reviewer',photo:x.authorAttribution?.photoUri||x.authorAttribution?.photoURI||'',rating:Number(x.rating||0),text:x.text?.text||'',relativeTime:x.relativePublishTimeDescription||'',googleMapsUri:x.googleMapsUri||d.googleMapsUri||c.env.MAPS_URL||'https://maps.google.com/?cid=17848990732573835237&entry=gps'})).filter((x:any)=>x.rating>=4);return c.json({reviews,rating:d.rating||null,count:d.userRatingCount||0,mapsUrl:d.googleMapsUri||c.env.MAPS_URL||'https://maps.google.com/?cid=17848990732573835237&entry=gps'});}catch(e){return c.json({reviews:[],rating:null,count:0,mapsUrl:c.env.MAPS_URL||'https://maps.google.com/?cid=17848990732573835237&entry=gps',error:'Google Places request failed'},502)}});

async function sha256(value:string){const d=await crypto.subtle.digest('SHA-256',enc.encode(value));return b64u(d)}
async function setupSignature(id:string,env:Env){return hmac(env,`setup:${id}`)}
async function sendSetupCode(c:any,email:string,code:string){
  if(!c.env.RESEND_API_KEY||!c.env.RESEND_FROM_EMAIL)throw new Error('Email verification is not configured. Add RESEND_API_KEY and RESEND_FROM_EMAIL to the Worker.');
  const resp=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:`Bearer ${c.env.RESEND_API_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({from:c.env.RESEND_FROM_EMAIL,to:[email],subject:'Your Impression Photography admin verification code',html:`<div style="font-family:Arial,sans-serif;max-width:560px;margin:auto;color:#171b1e"><h2>Impression Photography</h2><p>Use this verification code to create the Owner account for the private admin area:</p><p style="font-size:32px;font-weight:700;letter-spacing:8px">${code}</p><p>This code expires in 10 minutes. If you did not request this, you can ignore this email.</p></div>`})});
  if(!resp.ok){const detail=await resp.text().catch(()=> '');throw new Error(detail||'Could not send verification email')}
}
app.get('/api/setup/status',async c=>{const row:any=await c.env.DB.prepare('SELECT id FROM admins LIMIT 1').first();const ownerEmails=setupOwnerEmails(c.env);return c.json({available:!row&&ownerEmails.length>0,configured:Boolean(row),emailConfigured:Boolean(c.env.RESEND_API_KEY&&c.env.RESEND_FROM_EMAIL),ownerEmailConfigured:ownerEmails.length>0});});
