app.post('/api/admin/photos',requireAuth,async c=>{let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const id=uid();const bytes=finiteNumber(b.bytes,0,30*1024*1024,0);if(bytes<0)return c.json({error:'Invalid file size'},400);const caption=textField(b.caption,2000),occasion=textField(b.occasion||b.category||'Other',100),category=textField(b.category||b.occasion||'Other',100);const status=['pending','approved','rejected'].includes(String(b.status||'pending'))?String(b.status||'pending'):'pending';if(String(b.caption||'').length>2000||String(b.category||b.occasion||'Other').length>100)return c.json({error:'Photo fields are too long'},400);const reservationId=String(b.reservation_id||'');if(b.r2_key&&!reservationId)return c.json({error:'R2-backed photos require a valid upload reservation'},400);if(reservationId){const reservation:any=await c.env.DB.prepare('SELECT * FROM storage_reservations WHERE id=?').bind(reservationId).first();if(!reservation||Number(reservation.bytes)!==bytes||Number(reservation.expires_at)<Date.now())return c.json({error:'Upload reservation expired. Please upload the photo again.'},409);if(b.r2_key!==reservation.key)return c.json({error:'Upload reservation does not match the photo'},400);try{await c.env.DB.batch([c.env.DB.prepare(`INSERT INTO photos(id,source,source_id,r2_key,image_url,caption,occasion,category,status,published,width,height,bytes,sharpness,brightness,exposure,contrast,clarity,color,composition,similarity,total_score,phash) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,b.source||'upload',b.source_id||null,b.r2_key,b.image_url,caption,occasion,category,status,b.published?1:0,b.width||null,b.height||null,bytes,b.sharpness||0,b.brightness||0,b.exposure||0,b.contrast||0,b.clarity||0,b.color||0,b.composition||0,b.similarity||0,b.total_score||0,b.phash||null),c.env.DB.prepare('DELETE FROM storage_reservations WHERE id=?').bind(reservationId),c.env.DB.prepare('UPDATE storage_quota SET reserved_bytes=MAX(0,reserved_bytes-?) WHERE id=1').bind(bytes),c.env.DB.prepare('DELETE FROM upload_nonces WHERE reservation_id=?').bind(reservationId)]);return c.json({id})}catch(e){if(c.env.MEDIA&&reservation.key)await c.env.MEDIA.delete(reservation.key).catch(()=>{});await c.env.DB.batch([c.env.DB.prepare('DELETE FROM photos WHERE id=?').bind(id),c.env.DB.prepare('DELETE FROM storage_reservations WHERE id=?').bind(reservationId),c.env.DB.prepare('UPDATE storage_quota SET reserved_bytes=MAX(0,reserved_bytes-?) WHERE id=1').bind(bytes),c.env.DB.prepare('DELETE FROM upload_nonces WHERE reservation_id=?').bind(reservationId)]).catch(()=>{});return c.json({error:'Photo record could not be created; the uploaded file was cleaned up.'},500)}}const used=await storageUsed(c);if(Number(used)+bytes>2147483648)return c.json({error:'2 GB storage limit reached'},413);await c.env.DB.prepare(`INSERT INTO photos(id,source,source_id,r2_key,image_url,caption,occasion,category,status,published,width,height,bytes,sharpness,brightness,exposure,contrast,clarity,color,composition,similarity,total_score,phash) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id,b.source||'upload',b.source_id||null,b.r2_key||null,b.image_url||null,caption,occasion,category,status,b.published?1:0,b.width||null,b.height||null,bytes,b.sharpness||0,b.brightness||0,b.exposure||0,b.contrast||0,b.clarity||0,b.color||0,b.composition||0,b.similarity||0,b.total_score||0,b.phash||null).run();return c.json({id});});
app.post('/api/admin/upload-url',requireAuth,async c=>{if(!c.env.MEDIA)return c.json({error:'Photo storage is not enabled yet. Please connect R2 storage before uploading.'},503);let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const size=Number(b.size||0);const contentType=String(b.contentType||'').toLowerCase();if(!Number.isInteger(size)||size<=0||size>30*1024*1024)return c.json({error:'File must be 1 byte–30 MB'},400);if(contentType!=='image/webp')return c.json({error:'Uploads must be converted to WebP first'},415);const reservationId=uid();if(!(await reserveStorage(c,reservationId,size)))return c.json({error:'2 GB storage limit reached'},413);const safe=String(b.name||'photo.webp').replace(/[^a-zA-Z0-9._-]/g,'_').replace(/\.[^.]+$/,'')+'.webp';const key=`photos/${new Date().toISOString().slice(0,10)}/${uid()}-${safe}`;const exp=Date.now()+600000;const nonce=uid();await c.env.DB.prepare('UPDATE storage_reservations SET key=? WHERE id=?').bind(key,reservationId).run();try{await c.env.DB.prepare('INSERT INTO upload_nonces(id,reservation_id,key,expected_size,content_type,expires_at,used_at) VALUES(?,?,?,?,?,?,NULL)').bind(nonce,reservationId,key,size,contentType,exp).run();}catch(e){await releaseStorage(c,reservationId);return c.json({error:'Could not prepare upload'},500)}const url=new URL(c.req.url);url.pathname=`/api/upload/${encodeURIComponent(key)}`;url.search=`?expires=${exp}&nonce=${encodeURIComponent(nonce)}`;const token=await hmac(c.env,`PUT:${key}:${size}:${contentType}:${exp}:${nonce}`);url.search+=`&token=${encodeURIComponent(token)}`;return c.json({key,url:url.toString(),expires:exp,reservationId});});
app.put('/api/upload/:key',async c=>{if(!c.env.MEDIA)return c.json({error:'Photo storage is not enabled yet.'},503);const key=decodeURIComponent(c.req.param('key'));const u=new URL(c.req.url);const token=u.searchParams.get('token')||'';const exp=Number(u.searchParams.get('expires')||0);const nonce=u.searchParams.get('nonce')||'';const row:any=await c.env.DB.prepare('SELECT * FROM upload_nonces WHERE id=? AND key=?').bind(nonce,key).first();if(!row||row.used_at||Number(row.expires_at)<Date.now())return c.json({error:'Upload URL expired or already used'},403);const contentType=(c.req.header('Content-Type')||'').toLowerCase();const expected=Number(row.expected_size||0);if(!key.toLowerCase().endsWith('.webp')||contentType!=='image/webp'||exp!==Number(row.expires_at)||token!==await hmac(c.env,`PUT:${key}:${expected}:${contentType}:${exp}:${nonce}`))return c.json({error:'Invalid upload authorization'},403);if(!c.req.raw.body)return c.json({error:'No body'},400);const buf=await c.req.raw.arrayBuffer();if(buf.byteLength!==expected||buf.byteLength>30*1024*1024)return c.json({error:'Uploaded file size does not match the signed request'},413);const claimed=await c.env.DB.prepare('UPDATE upload_nonces SET used_at=? WHERE id=? AND used_at IS NULL').bind(Date.now(),nonce).run();if(Number(claimed.meta?.changes||0)!==1)return c.json({error:'Upload URL already used'},409);try{await c.env.MEDIA.put(key,buf,{httpMetadata:{contentType:'image/webp',cacheControl:'public,max-age=31536000,immutable'}});await c.env.DB.prepare('UPDATE upload_nonces SET uploaded_at=? WHERE id=?').bind(Date.now(),nonce).run();return c.json({ok:true,key,reservationId:row.reservation_id});}catch(e){await c.env.MEDIA.delete(key).catch(()=>{});await releaseStorage(c,row.reservation_id||'');return c.json({error:'Storage upload failed'},502)}});
async function syncInstagramData(c:any){
  let conn=await getInstagramConnection(c);
  if(!conn)return {ok:false,error:'Instagram is not connected. Open the Connect Instagram link first.',status:400};
  conn=await refreshInstagramToken(c,conn);
  const version=c.env.INSTAGRAM_GRAPH_VERSION||'v24.0';
  let endpoint=`https://graph.instagram.com/${version}/${encodeURIComponent(conn.user_id)}/media?fields=id,caption,media_type,media_product_type,media_url,thumbnail_url,permalink,timestamp&limit=50&access_token=${encodeURIComponent(conn.access_token)}`;
  let photosImported=0,reelsImported=0,skipped=0,pages=0;
  while(endpoint&&pages<20){
    const resp=await fetch(endpoint);const data:any=await resp.json();
    if(!resp.ok)return {ok:false,error:data?.error?.message||'Instagram API request failed',status:502,photosImported,reelsImported,skipped};
    for(const item of(data.data||[])){
      const category=instagramCategory(item.caption||'');
      const isReel=item.media_type==='VIDEO'&&(item.media_product_type==='REELS'||/\/reel\//i.test(item.permalink||''));
      if(isReel){
        const exists=await c.env.DB.prepare('SELECT id FROM videos WHERE source_url=?').bind(item.permalink||'').first();
        if(exists){skipped++;continue}
        await c.env.DB.prepare(`INSERT INTO videos(id,title,embed_url,platform,source_url,video_id,category,active,sort_order) VALUES(?,?,?,?,?,?,?,?,?)`).bind(uid(),item.caption?.split('\n')[0]?.slice(0,100)||'Instagram Reel',item.permalink||'','instagram',item.permalink||'',item.id,category,1,reelsImported).run();
        reelsImported++;continue;
      }
      if(item.media_type!=='IMAGE'||!item.media_url){skipped++;continue}
      const exists=await c.env.DB.prepare('SELECT id FROM photos WHERE source=? AND source_id=?').bind('instagram',item.id).first();
      if(exists){skipped++;continue}
      if(!c.env.MEDIA){
        // Keep the Instagram CDN URL for testing/fallback deployments. Production should bind R2 for durable photo storage.
        await c.env.DB.prepare(`INSERT INTO photos(id,source,source_id,r2_key,image_url,caption,occasion,category,status,published,width,height,bytes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(uid(),'instagram',item.id,null,item.media_url,item.caption||'',category,category,'pending',0,null,null,0).run();
        photosImported++;continue;
      }
      const img=await fetch(item.media_url,{cf:{image:{format:'webp',quality:86}} as any});
      if(!img.ok){skipped++;continue}
      const buf=await img.arrayBuffer();const bytes=buf.byteLength;const key=`photos/instagram/${item.id}.webp`;const reservationId=uid();
      if(!(await reserveStorage(c,reservationId,bytes)))return {ok:false,error:'2 GB storage limit reached while importing Instagram photos',status:413,photosImported,reelsImported,skipped};
      try{await c.env.MEDIA.put(key,buf,{httpMetadata:{contentType:'image/webp',cacheControl:'public,max-age=31536000,immutable'}});await c.env.DB.batch([c.env.DB.prepare(`INSERT INTO photos(id,source,source_id,r2_key,image_url,caption,occasion,category,status,published,width,height,bytes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(uid(),'instagram',item.id,key,'/media/'+key,item.caption||'',category,category,'pending',0,null,null,bytes),c.env.DB.prepare('DELETE FROM storage_reservations WHERE id=?').bind(reservationId),c.env.DB.prepare('UPDATE storage_quota SET reserved_bytes=MAX(0,reserved_bytes-?) WHERE id=1').bind(bytes)]);photosImported++;}catch{await c.env.MEDIA.delete(key).catch(()=>{});await releaseStorage(c,reservationId);skipped++;}
    }
    endpoint=data.paging?.next||'';pages++;
  }
  return {ok:true,photosImported,reelsImported,skipped,pages,photoStorageEnabled:Boolean(c.env.MEDIA),username:conn.username||null};
}
app.post('/api/admin/instagram/sync',requireAuth,async c=>{try{const result:any=await syncInstagramData(c);return c.json(result,result.ok?200:(result.status||500) as any)}catch(e:any){return c.json({error:String(e?.message||e||'Instagram sync failed')},502)}});
app.post('/api/admin/youtube/sync',requireAuth,async c=>{if(!c.env.YOUTUBE_API_KEY)return c.json({error:'YouTube is not connected. Add YOUTUBE_API_KEY to Worker secrets.'},400);const handle=c.env.YOUTUBE_CHANNEL_HANDLE||'@impressionphotography9904';const base='https://www.googleapis.com/youtube/v3';const ch=await fetch(`${base}/channels?part=contentDetails&forHandle=${encodeURIComponent(handle)}&key=${encodeURIComponent(c.env.YOUTUBE_API_KEY)}`);const chData:any=await ch.json();if(!ch.ok||!chData.items?.[0])return c.json({error:chData?.error?.message||'YouTube channel not found'},502);const uploads=chData.items[0].contentDetails.relatedPlaylists.uploads;let pageToken='',imported=0,skipped=0,pages=0;do{const url=`${base}/playlistItems?part=snippet,contentDetails,status&playlistId=${encodeURIComponent(uploads)}&maxResults=50${pageToken?`&pageToken=${encodeURIComponent(pageToken)}`:''}&key=${encodeURIComponent(c.env.YOUTUBE_API_KEY)}`;const r=await fetch(url);const data:any=await r.json();if(!r.ok)return c.json({error:data?.error?.message||'YouTube API request failed',imported,skipped},502);for(const item of(data.items||[])){const id=item.contentDetails?.videoId||item.snippet?.resourceId?.videoId;if(!id||item.status?.privacyStatus!=='public')continue;const sourceUrl=`https://www.youtube.com/watch?v=${id}`;const exists=await c.env.DB.prepare('SELECT id FROM videos WHERE source_url=?').bind(sourceUrl).first();if(exists){skipped++;continue}const title=String(item.snippet?.title||'YouTube Video');const category=instagramCategory(item.snippet?.description||'');await c.env.DB.prepare(`INSERT INTO videos(id,title,embed_url,platform,source_url,video_id,category,active,sort_order) VALUES(?,?,?,?,?,?,?,?,?)`).bind(uid(),title,`https://www.youtube.com/embed/${encodeURIComponent(id)}?enablejsapi=1&playsinline=1&rel=0&modestbranding=1`,'youtube',sourceUrl,id,category,1,imported).run();imported++}pageToken=data.nextPageToken||'';pages++;if(pages>=20)pageToken='';}while(pageToken);return c.json({ok:true,imported,skipped,handle,pages});});
app.get('/media/*',async c=>{if(!c.env.MEDIA)return c.notFound();const key=c.req.path.replace(/^\/media\//,'');const obj=await c.env.MEDIA.get(key);if(!obj)return c.notFound();const h=new Headers();obj.writeHttpMetadata(h);h.set('etag',obj.httpEtag);return new Response(obj.body,{headers:h});});
app.patch('/api/admin/photos/:id',requireAuth,async c=>{let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const out:any={};if('occasion' in b){if(String(b.occasion).length>100)return c.json({error:'Occasion is too long'},400);out.occasion=textField(b.occasion,100)}if('category' in b){if(String(b.category).length>100)return c.json({error:'Category is too long'},400);out.category=textField(b.category,100)}if('status' in b){if(!['pending','approved','rejected'].includes(String(b.status)))return c.json({error:'Invalid photo status'},400);out.status=String(b.status)}if('published' in b){if(typeof b.published!=='boolean'&&b.published!==0&&b.published!==1)return c.json({error:'Invalid published value'},400);out.published=b.published?1:0}if('caption' in b){if(String(b.caption).length>2000)return c.json({error:'Caption is too long'},400);out.caption=textField(b.caption,2000)}if('total_score' in b){const n=Number(b.total_score);if(!Number.isFinite(n)||n<-100000||n>100000)return c.json({error:'Invalid score'},400);out.total_score=n}const keys=Object.keys(out);if(!keys.length)return c.json({ok:true});await c.env.DB.prepare(`UPDATE photos SET ${keys.map(x=>`${x}=?`).join(',')},updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(...keys.map(k=>out[k]),c.req.param('id')).run();return c.json({ok:true});});
app.delete('/api/admin/photos/:id',requireAuth,async c=>{const id=c.req.param('id');const p:any=await c.env.DB.prepare('SELECT r2_key FROM photos WHERE id=?').bind(id).first();if(p?.r2_key&&c.env.MEDIA)await c.env.MEDIA.delete(p.r2_key);await c.env.DB.prepare('DELETE FROM photos WHERE id=?').bind(id).run();return c.json({ok:true});});
app.get('/api/admin/services',requireAuth,async c=>c.json((await c.env.DB.prepare('SELECT id,title,description,image_url,active,sort_order FROM services ORDER BY sort_order,id').all()).results));
app.post('/api/admin/services',requireAuth,async c=>{let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const title=textField(b.title,200),description=textField(b.description,5000),imageUrl=textField(b.image_url,2048),sortOrder=boundedInt(b.sort_order,-10000,10000,0),price=finiteNumber(b.price,0,100000000,0);if(!title)return c.json({error:'Service title is required'},400);if(!validMediaUrl(imageUrl))return c.json({error:'Image URL must use http(s) or /media/'},400);if(String(b.title||'').length>200||String(b.description||'').length>5000||String(b.image_url||'').length>2048)return c.json({error:'Service fields are too long'},400);const id=textField(b.id,100)||uid();await c.env.DB.prepare(`INSERT INTO services(id,title,description,price,image_url,active,sort_order) VALUES(?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title,description=excluded.description,price=excluded.price,image_url=excluded.image_url,active=excluded.active,sort_order=excluded.sort_order`).bind(id,title,description,price,imageUrl,b.active===false?0:1,sortOrder).run();return c.json({ok:true,id});});
app.delete('/api/admin/services/:id',requireAuth,async c=>{await c.env.DB.prepare('DELETE FROM services WHERE id=?').bind(c.req.param('id')).run();return c.json({ok:true});});
app.get('/api/admin/videos',requireAuth,async c=>c.json((await c.env.DB.prepare('SELECT * FROM videos ORDER BY sort_order,id').all()).results));
app.post('/api/admin/videos',requireAuth,async c=>{let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const id=textField(b.id,100)||uid();const platform=['youtube','instagram','vimeo'].includes(String(b.platform||''))?String(b.platform):'youtube';const sourceUrl=textField(b.source_url||b.embed_url,2048);const title=textField(b.title,200);const category=textField(b.category||'Other',100);if(!title||!sourceUrl)return c.json({error:'Title and video link are required'},400);if(String(b.title||'').length>200||String(b.source_url||b.embed_url||'').length>2048||String(b.category||'Other').length>100)return c.json({error:'Video fields are too long'},400);let videoId='';let embedUrl=sourceUrl;try{const u=new URL(sourceUrl);if(platform==='youtube'){if(u.hostname.includes('youtu.be'))videoId=u.pathname.slice(1).split('/')[0];else if(u.searchParams.get('v'))videoId=u.searchParams.get('v')||'';else videoId=u.pathname.match(/\/(?:embed|shorts|live)\/([^/?]+)/)?.[1]||'';if(!videoId)return c.json({error:'Invalid YouTube link'},400);embedUrl=`https://www.youtube.com/embed/${encodeURIComponent(videoId)}?enablejsapi=1&playsinline=1&rel=0&modestbranding=1`;}else if(platform==='instagram'){if(!/instagram\.com$/i.test(u.hostname)&&!/\.instagram\.com$/i.test(u.hostname))return c.json({error:'Invalid Instagram link'},400);const m=u.pathname.match(/\/reel\/([^/?#]+)/);if(!m)return c.json({error:'Use an Instagram Reel URL'},400);embedUrl=`https://www.instagram.com/reel/${m[1]}/embed/?hidecaption=1`;}else if(platform==='vimeo'){if(!/(^|\.)vimeo\.com$/i.test(u.hostname))return c.json({error:'Invalid Vimeo link'},400);embedUrl=sourceUrl;}}catch{return c.json({error:'Invalid video URL'},400)}await c.env.DB.prepare(`INSERT INTO videos(id,title,embed_url,platform,source_url,video_id,category,active,sort_order) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title,embed_url=excluded.embed_url,platform=excluded.platform,source_url=excluded.source_url,video_id=excluded.video_id,category=excluded.category,active=excluded.active,sort_order=excluded.sort_order`).bind(id,title,embedUrl,platform,sourceUrl,videoId,category,b.active===false?0:1,boundedInt(b.sort_order,-10000,10000,0)).run();return c.json({ok:true,id});});
app.delete('/api/admin/videos/:id',requireAuth,async c=>{await c.env.DB.prepare('DELETE FROM videos WHERE id=?').bind(c.req.param('id')).run();return c.json({ok:true});});
app.get('/api/admin/admins',requireAuth,async c=>{const me:any=c.get('admin');if(me.role!=='owner')return c.json({error:'Owner only'},403);return c.json((await c.env.DB.prepare('SELECT id,name,email,role,active,created_at FROM admins ORDER BY created_at').all()).results)});
app.post('/api/admin/admins',requireAuth,async c=>{const me:any=c.get('admin');if(me.role!=='owner')return c.json({error:'Owner only'},403);let b:any;try{b=await c.req.json()}catch{return c.json({error:'Invalid request'},400)}const name=textField(b.name,100),email=String(b.email||'').trim().toLowerCase(),password=String(b.password||'');if(!name||!validEmail(email)||password.length<12||password.length>128)return c.json({error:'Name, valid email, and a 12–128 character password are required'},400);if(String(b.name||'').length>100)return c.json({error:'Name is too long'},400);try{await c.env.DB.prepare('INSERT INTO admins(id,name,email,password_hash,role) VALUES(?,?,?,?,?)').bind(uid(),name,email,await hashPassword(password),b.role==='owner'?'owner':'admin').run();return c.json({ok:true})}catch(e:any){if(String(e?.message||'').toLowerCase().includes('unique'))return c.json({error:'That email is already an admin'},409);return c.json({error:'Could not create admin'},500)}});
app.delete('/api/admin/admins/:id',requireAuth,async c=>{const me:any=c.get('admin');if(me.role!=='owner')return c.json({error:'Owner only'},403);if(c.req.param('id')===me.id)return c.json({error:'Cannot delete yourself'},400);await c.env.DB.prepare('DELETE FROM admins WHERE id=?').bind(c.req.param('id')).run();return c.json({ok:true});});
app.post('/api/analytics',async c=>{const day=new Date().toISOString().slice(0,10);const m=c.req.header('sec-ch-ua-mobile')==='?1';const ua=(c.req.header('user-agent')||'').toLowerCase();const device=m?'mobile':(/ipad|tablet|android(?!.*mobile)/.test(ua)?'tablet':'desktop');const seen=getCookie(c,'ip_visitor')==='1';await c.env.DB.prepare(`INSERT INTO analytics_daily(day,visitors,pageviews,mobile,desktop,tablet,other) VALUES(?,${seen?0:1},1,${device==='mobile'?1:0},${device==='desktop'?1:0},${device==='tablet'?1:0},${device==='other'?1:0}) ON CONFLICT(day) DO UPDATE SET visitors=visitors+excluded.visitors,pageviews=pageviews+1,mobile=mobile+excluded.mobile,desktop=desktop+excluded.desktop,tablet=tablet+excluded.tablet,other=other+excluded.other`).bind(day).run();if(!seen)setCookie(c,'ip_visitor','1',{httpOnly:true,secure:true,sameSite:'Lax',path:'/',maxAge:86400});return c.json({ok:true});});
app.all('*',c=>c.env.ASSETS?.fetch(c.req.raw) || c.notFound());
export default {fetch:app.fetch,scheduled:async(_controller:any,env:Env)=>{try{const now=Date.now();const orphaned:any=await env.DB.prepare('SELECT id,reservation_id,key FROM upload_nonces WHERE uploaded_at IS NOT NULL AND uploaded_at<? LIMIT 100').bind(now-60*60*1000).all();for(const n of(orphaned.results||[])){const photo:any=await env.DB.prepare('SELECT id FROM photos WHERE r2_key=? LIMIT 1').bind(n.key).first();if(photo){await env.DB.prepare('DELETE FROM upload_nonces WHERE id=?').bind(n.id).run();continue}if(env.MEDIA)await env.MEDIA.delete(n.key).catch(()=>{});await releaseStorage({env} as any,n.reservation_id);await env.DB.prepare('DELETE FROM upload_nonces WHERE id=?').bind(n.id).run();}await env.DB.batch([env.DB.prepare('DELETE FROM sessions WHERE expires_at<=?').bind(now),env.DB.prepare('DELETE FROM setup_verifications WHERE used_at IS NOT NULL OR expires_at<?').bind(now),env.DB.prepare('DELETE FROM auth_rate_limits WHERE window_start<? AND blocked_until<?').bind(now-24*60*60*1000,now),env.DB.prepare('DELETE FROM upload_nonces WHERE expires_at<? AND uploaded_at IS NULL').bind(now)]);const stale:any=await env.DB.prepare('SELECT id FROM storage_reservations WHERE expires_at<?').bind(now).all();for(const r of(stale.results||[]))await releaseStorage({env} as any,r.id);await syncInstagramData({env})}catch{}}};
